int boundedLanguage(int value) noexcept { return value >= 0 && value < languageCount ? value : 0; }
struct Entry { juce::String source; std::array<juce::String, languageCount> values; };
const std::vector<Entry>& catalog() {
    static const auto entries=[] {
        std::vector<Entry> result; result.reserve(std::size(rows));
        for (const auto& row : rows) {
            Entry entry; entry.source=juce::String::fromUTF8(row.source);
            for (size_t i=0;i<entry.values.size();++i)entry.values[i]=juce::String::fromUTF8(row.values[i]);
            result.push_back(std::move(entry));
        }
        return result;
    }();
    return entries;
}
bool isNumber(const juce::String& text) {
    return text.isNotEmpty() && text.containsOnly("+-0123456789.,") && text.containsAnyOf("0123456789");
}
bool numericTemplate(const juce::String& input,const juce::String& pattern,const juce::String& translated,juce::String& result) {
    const int marker=pattern.indexOf("{0}");if(marker<0)return false;
    const auto prefix=pattern.substring(0,marker),suffix=pattern.substring(marker+3);
    if(!input.startsWith(prefix)||!input.endsWith(suffix)||input.length()<prefix.length()+suffix.length()+1)return false;
    const auto value=input.substring(prefix.length(),input.length()-suffix.length());
    if(!isNumber(value))return false;
    result=translated.replace("{0}",value);return true;
}
bool liveReadout(const juce::String& input,int language,juce::String& result) {
    struct Readout {const char* prefix;const char* suffix;};
    for(const auto& field:{Readout{"Okunan bolge: "," s"},Readout{"Etkin onarim karisimi: ","%"},Readout{"12 sn ornek: ","%"},Readout{"Uygulanan ayar sayisi: ",""}}){
        const juce::String key(field.prefix),suffix(field.suffix);
        for(int alias:{3,0}){
            const auto prefix=alias==3?key:localize(key,0);
            if(numericTemplate(input,prefix+"{0}"+suffix,localize(key,language)+"{0}"+suffix,result))return true;
        }
    }
    for(const char* key:{"Hazir bolgesel ses / canli olcumler: ","Etkin gecis: "}){
        for(int alias:{3,0}){
            const juce::String raw(key);const auto prefix=alias==3?raw:localize(raw,0);
            const auto middle=alias==3?juce::String(" ms | Etkin miktar: "):localize(" ms | Etkin miktar: ",0);
            if(!input.startsWith(prefix)||!input.endsWithChar('%'))continue;
            const int split=input.indexOf(prefix.length(),middle);if(split<0)continue;
            const auto time=input.substring(prefix.length(),split),amount=input.substring(split+middle.length(),input.length()-1);
            if(!isNumber(time)||!isNumber(amount))continue;
            result=localize(raw,language)+time+localize(" ms | Etkin miktar: ",language)+amount+"%";return true;
        }
    }
    return false;
}
// A ticker event has a strict numeric timestamp and fixed engine field markers.
// This function is deliberately not a word-replacement pass over arbitrary text.
bool tickerEvent(const juce::String& input,int language,juce::String& result) {
    const int seconds=input.indexOf(" s | ");if(seconds<=0||!isNumber(input.substring(0,seconds)))return false;
    const int dsp=input.indexOf(seconds+5," | DSP ");if(dsp<0)return false;
    const int transition=input.indexOf(dsp+7," c | gecis ");if(transition<0)return false;
    const int amount=input.indexOf(transition+11," ms | miktar ");if(amount<0)return false;
    const auto note=input.substring(seconds+5,dsp),shift=input.substring(dsp+7,transition),time=input.substring(transition+11,amount);
    const auto tail=input.substring(amount+13);const int percent=tail.indexOfChar('%');if(percent<1)return false;
    const auto value=tail.substring(0,percent),end=tail.substring(percent+1);
    if(note.isEmpty()||!note.containsOnly("ABCDEFGabcdefgDoReMiFaSolLaSi#b0123456789- ")||!isNumber(shift)||!isNumber(time)||!isNumber(value)||(end.isNotEmpty()&&end!=" | hafiza"))return false;
    result=input.substring(0,seconds)+" s | "+note+" | DSP "+shift+" c"+localize(" | gecis ",language)+time+localize(" ms | miktar ",language)+value+"%"+(end.isEmpty()?juce::String{}:localize(" | hafiza",language));
    return true;
}
