juce::String languageName(int language) {
    static constexpr const char* names[]={"English","中文（简体）","Deutsch","Türkçe","Français","العربية","Español","Português","Italiano"};
    return juce::String::fromUTF8(names[boundedLanguage(language)]);
}
juce::String languageCode(int language) {
    static constexpr const char* codes[]={"en","zh-Hans","de","tr","fr","ar","es","pt","it"};
    return juce::String(codes[boundedLanguage(language)]);
}
bool rightToLeft(int language) noexcept { return boundedLanguage(language)==5; }
juce::StringArray localizationKeys() {
    juce::StringArray result;for(const auto& entry:catalog())result.add(entry.source);return result;
}
juce::String localize(const juce::String& text,int language) {
    const int index=boundedLanguage(language);
    for(const auto& entry:catalog())
        if(text==entry.source||text==entry.values[0]||text==entry.values[3])return entry.values[size_t(index)];
    if(text=="User note")return localize("KULLANICI NOTU",language);
    return text;
}
juce::String localizeStatus(const juce::String& text,int language) {
    const auto exact=localize(text,language);if(exact!=text)return exact;
    juce::String translated;
    for(const auto& entry:catalog()) {
        if(!entry.source.contains("{0}"))continue;
        for(const auto& pattern:{entry.source,entry.values[0],entry.values[3]})
            if(numericTemplate(text,pattern,entry.values[size_t(boundedLanguage(language))],translated))return translated;
    }
    if(liveReadout(text,language,translated)||tickerEvent(text,language,translated))return translated;
    // History consists of separate engine events, joined by a deliberately
    // distinct four-space delimiter. Unknown segments remain byte-for-byte.
    const juce::String separator="    |    ";const int split=text.indexOf(separator);
    if(split>=0&&text.length()<32768) {
        juce::String result;int at=0;
        while(at<=text.length()) {
            const int next=text.indexOf(at,separator);const auto piece=next<0?text.substring(at):text.substring(at,next);
            juce::String event;result+=tickerEvent(piece,language,event)?event:piece;
            if(next<0)break;result+=separator;at=next+separator.length();
        }
        return result;
    }
    return text;
}
